/**
 * The canonical data behind the library-adapter READMEs, and the one function
 * that turns an authored snippet into the blocks a reader sees.
 *
 * Both `generate-package-readmes.mjs` and `check-readme-drift.mjs` import this,
 * so the generator cannot render a snippet the check does not understand — and
 * the check cannot pass on content the generator invented.
 *
 * Two sources, both in `apps/docs/lib/libraries.tsx`:
 *
 *   - `FRAMEWORK_RECIPES` — every command and every snippet, per library and
 *     framework. Generated by `scripts/docs/generate-library-recipes.mjs`, and
 *     the same table the documentation page renders.
 *   - `rawLibraries` — package identity (name, docs URL, bridge family), the
 *     token→target mapping and the exported API surface.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";

const REPO = join(import.meta.dirname, "..", "..");
const SOURCE = join(REPO, "apps", "docs", "lib", "libraries.tsx");

/** The frameworks a library may be documented for, in display order. */
export const FRAMEWORK_ORDER = [
  "React",
  "Next.js",
  "Remix",
  "Astro",
  "Vue 3",
  "Nuxt",
  "Svelte",
  "Solid",
  "Angular",
];

/**
 * The recipe fields that carry a snippet, in the order a reader meets them.
 * `check-readme-drift.mjs` asserts the README reproduces exactly these, in this
 * order — a field added to the recipe schema cannot be silently dropped.
 */
export const SNIPPET_FIELDS = [
  "setup",
  "mountProvider",
  "code",
  "componentExample",
  "themeSwitchExample",
  "completeExample",
];

/**
 * The banner that separates files inside one authored snippet.
 *
 * Identical to the pattern the documentation page uses (`splitRecipeFiles` in
 * `app/libraries/[slug]/page.tsx`).
 */
export const FILE_BANNER =
  /^(?:\/\/|<!--)\s*-{3,}\s*([\w./@-]+\.[a-z]{2,6})\s*(?:-->)?$/;

/** A leading `// path` comment in a single-file snippet, per the docs. */
export const LEADING_PATH = /^(?:\/\/|<!--|#)\s*([\w./@-]+\.[a-z]{2,6})/;

/** The fence language for a file, from its extension. */
export const LANG_BY_EXT = {
  css: "css",
  json: "json",
  ts: "ts",
  tsx: "tsx",
  js: "js",
  mjs: "js",
  cjs: "js",
  vue: "vue",
  svelte: "svelte",
  astro: "astro",
  html: "html",
};

const source = readFileSync(SOURCE, "utf8");

/**
 * `FRAMEWORK_RECIPES` — every field is emitted by the recipe generator as a
 * single line of JSON, so the block is parsed with `JSON.parse` per field. A
 * snippet containing `},` cannot end an entry early.
 */
export function readRecipes() {
  const at = source.indexOf("export const FRAMEWORK_RECIPES");
  if (at < 0) throw new Error("FRAMEWORK_RECIPES not found in libraries.tsx");
  const block = source.slice(
    at,
    source.indexOf("\nexport const FRAMEWORK_LANG", at),
  );

  const recipes = {};
  for (const m of block.matchAll(/^ {2}"([a-z-]+\/[^"]+)": \{$/gm)) {
    const body = block.slice(m.index + m[0].length);
    const end = body.search(/\n {2}\},/);
    if (end < 0) throw new Error(`unterminated recipe entry: ${m[1]}`);

    const fields = {};
    for (const line of body.slice(0, end).split("\n")) {
      const f = line.match(/^ {4}"(\w+)": (.*),$/);
      if (f) fields[f[1]] = JSON.parse(f[2]);
    }
    recipes[m[1]] = fields;
  }
  if (!Object.keys(recipes).length) throw new Error("no recipes parsed");
  return recipes;
}

/**
 * `rawLibraries` — the per-library identity and the API surface.
 *
 * The fields read here are single-line string and array literals, which is what
 * makes the extraction exact. A missing field throws rather than rendering a
 * blank README.
 */
export function readLibraries() {
  const at = source.indexOf("export const rawLibraries");
  if (at < 0) throw new Error("rawLibraries not found in libraries.tsx");
  const block = source.slice(at, source.indexOf("\n];", at));

  const out = {};
  for (const part of block.split(/\n  \{\n/).slice(1)) {
    const pick = (re) => (part.match(re) ?? [])[1];
    const slug = pick(/slug: "([a-z0-9-]+)"/);
    if (!slug) continue;

    const tags = (part.match(/tags: \[([^\]]*)\]/) ?? [])[1];
    const mapping = [
      ...part.matchAll(/\{ role: "([^"]+)", target: "([^"]+)" \}/g),
    ].map((m) => ({ role: m[1], target: m[2] }));

    const groups = [];
    for (const g of part.matchAll(
      /label: "([^"]+)",\n\s+features: \[([\s\S]*?)\n\s+\],/g,
    )) {
      groups.push({
        label: g[1],
        features: [
          ...g[2].matchAll(/name: "([^"]+)",\n\s+desc:\s*\n?\s*"([^"]*)"/g),
        ].map((f) => ({ name: f[1], desc: f[2] })),
      });
    }

    const required = {
      name: pick(/name: "([^"]+)"/),
      pkg: pick(/pkg: "([^"]+)"/),
      officialUrl: pick(/officialUrl: "([^"]+)"/),
      architecture: pick(/architecture: "([a-z-]+)"/),
      kind: pick(/kind: "([^"]+)"/),
      tagline: pick(/tagline:\s*\n?\s*"([^"]*)"/),
    };
    for (const [field, value] of Object.entries(required)) {
      if (!value) throw new Error(`${slug}: could not read ${field}`);
    }

    out[slug] = {
      slug,
      ...required,
      tags: tags ? [...tags.matchAll(/"([^"]+)"/g)].map((t) => t[1]) : [],
      mapping,
      groups,
    };
  }
  return out;
}

/** Frameworks this library is documented for, in the docs' display order. */
export function frameworksOf(recipes, slug) {
  const present = Object.keys(recipes)
    .filter((key) => key.startsWith(`${slug}/`))
    .map((key) => key.slice(slug.length + 1));

  for (const fw of present) {
    if (!FRAMEWORK_ORDER.includes(fw)) {
      throw new Error(`${slug}: unknown framework ${fw}`);
    }
  }
  return FRAMEWORK_ORDER.filter((fw) => present.includes(fw));
}

/**
 * Splits a multi-file snippet into its files, exactly as the documentation page
 * does: the banner (or a leading path comment) becomes the block's filename and
 * is **removed** from the body, because the page shows that path in the block
 * toolbar rather than in the code.
 *
 * Reproducing that here is what keeps the two presentations byte-identical: a
 * `// ---- src/index.css` line left inside a CSS block would be an invalid
 * declaration in the README and absent from the page.
 */
export function splitFiles(text) {
  const chunks = [];
  let current = { filename: undefined, body: [] };

  for (const line of text.split("\n")) {
    const banner = line.trim().match(FILE_BANNER);
    if (banner) {
      if (current.body.length || current.filename) chunks.push(current);
      current = { filename: banner[1], body: [] };
      continue;
    }
    current.body.push(line);
  }
  if (current.body.length || current.filename) chunks.push(current);

  const only = chunks[0];
  if (chunks.length === 1 && only && !only.filename) {
    const first = (only.body[0] ?? "").trim();
    const lead = first.match(LEADING_PATH);
    if (lead) {
      only.filename = lead[1];
      if (first.startsWith("<!--") && !first.endsWith("-->")) {
        let i = 0;
        while (i < only.body.length && !(only.body[i] ?? "").includes("-->")) i += 1;
        only.body.splice(0, i + 1);
      } else {
        only.body.splice(0, 1);
      }
      if ((only.body[0] ?? "").trim() === "") only.body.splice(0, 1);
    }
  }

  return (
    chunks
      .map((chunk) => ({
        filename: chunk.filename,
        code: chunk.body.join("\n").replace(/^\n+|\n+$/g, ""),
      }))
      // A chunk that holds nothing but a path comment is a stray banner: the
      // daisyUI Angular recipe opens with `// .postcssrc.json` and then repeats
      // the same path as a `// ---- ` banner. The page renders it as an empty
      // block; a README has no empty code block to show, so it is dropped — the
      // file it names is rendered from the chunk that actually has the content.
      .filter((chunk) => chunk.code.trim())
      .filter((chunk, i, all) => {
        const lines = chunk.code.split("\n").filter((l) => l.trim());
        const bare = /^(?:\/\/|<!--|#)\s*[\w./@-]+\.[a-z]{2,6}\s*(?:-->)?$/;
        return !(lines.length === 1 && bare.test(lines[0].trim()) && all.length > 1 && i === 0);
      })
  );
}

/**
 * Every file of every snippet field for one library/framework, in reading
 * order. This is the list the README must reproduce, block for block.
 */
export function canonicalSnippets(recipes, slug, fw) {
  const recipe = recipes[`${slug}/${fw}`];
  const out = [];
  for (const field of SNIPPET_FIELDS) {
    const value = recipe[field];
    if (typeof value !== "string" || !value) continue;
    for (const file of splitFiles(value)) out.push({ field, ...file });
  }
  return out;
}

export { REPO, SOURCE };
